import { useKeyboard } from "@opentui/react";
import { useState, useMemo, useCallback, useEffect } from "react";

import { useTheme } from "@/components/ui/theme-provider";
import { useInputPaste } from "@/lib/input-paste";
import {
  decodePaste,
  getKeyText,
  toSingleLine,
} from "@/lib/input-utils";
import type { BorderStyle } from "@/components/ui/types";

export interface SearchInputProps<T = string> {
  options?: T[];
  getValue?: (item: T) => string;
  value?: string;
  onChange?: (query: string) => void;
  onSelect?: (item: T) => void;
  placeholder?: string;
  label?: string;
  maxResults?: number;
  autoFocus?: boolean;
  focused?: boolean;
  isDisabled?: boolean;
  id?: string;
  borderStyle?: BorderStyle;
  paddingX?: number;
  cursor?: string;
  searchIcon?: string;
  resultCursor?: string;
}

export const SearchInput = <T = string,>({
  options,
  getValue,
  value: controlledValue,
  onChange,
  onSelect,
  placeholder = "Search...",
  label,
  maxResults = 5,
  autoFocus = false,
  focused,
  isDisabled = false,
  id,
  borderStyle = "rounded",
  paddingX = 1,
  cursor = "█",
  searchIcon = "🔍 ",
  resultCursor = "› ",
}: SearchInputProps<T>) => {
  const [internalValue, setInternalValue] = useState("");
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [showResults, setShowResults] = useState(false);
  const theme = useTheme();
  const isFocused = !isDisabled && (focused ?? autoFocus);

  const query = controlledValue ?? internalValue;

  const getItemValue = useCallback(
    (item: T): string => {
      if (getValue) {
        return getValue(item);
      }
      return String(item);
    },
    [getValue]
  );

  const setQuery = (newQuery: string) => {
    if (controlledValue === undefined) {
      setInternalValue(newQuery);
    }
    onChange?.(newQuery);
  };

  const filteredResults = useMemo(() => {
    if (!options || options.length === 0) {
      return [];
    }
    if (!query) {
      return options.slice(0, maxResults);
    }
    const lower = query.toLowerCase();
    return options
      .filter((item) => getItemValue(item).toLowerCase().includes(lower))
      .slice(0, maxResults);
  }, [options, query, maxResults, getItemValue]);

  useEffect(() => {
    if (selectedIndex >= filteredResults.length) {
      setSelectedIndex(Math.max(0, filteredResults.length - 1));
    }
  }, [filteredResults.length, selectedIndex]);

  const insertText = (input: string) => {
    if (!input) {
      return;
    }
    setQuery(query + input);
    setSelectedIndex(0);
    if (options && options.length > 0) {
      setShowResults(true);
    }
  };

  useKeyboard((key) => {
    if (!isFocused) {
      return;
    }
    if (key.name === "escape") {
      setQuery("");
      setShowResults(false);
      setSelectedIndex(0);
      return;
    }
    if (key.name === "up") {
      if (showResults && filteredResults.length > 0) {
        setSelectedIndex((i) => Math.max(0, i - 1));
      }
      return;
    }
    if (key.name === "down") {
      if (filteredResults.length > 0) {
        setShowResults(true);
        setSelectedIndex((i) => Math.min(filteredResults.length - 1, i + 1));
      }
      return;
    }
    if (key.name === "return") {
      if (showResults && filteredResults.length > 0) {
        const selected = filteredResults[selectedIndex];
        if (selected !== undefined) {
          onSelect?.(selected);
          setQuery(getItemValue(selected));
          setShowResults(false);
          setSelectedIndex(0);
        }
      }
      return;
    }
    if (key.name === "backspace" || key.name === "delete") {
      const newQuery = query.slice(0, -1);
      setQuery(newQuery);
      setSelectedIndex(0);
      if (newQuery.length === 0) {
        setShowResults(false);
      }
      return;
    }
    if (key.name === "tab") {
      return;
    }
    insertText(getKeyText(key));
  });

  useInputPaste((event) => {
    if (!isFocused) {
      return;
    }
    const input = toSingleLine(decodePaste(event.bytes));
    if (!input) {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    insertText(input);
  });

  const borderColor = isFocused ? theme.colors.focusRing : theme.colors.border;
  const hasResults = showResults && filteredResults.length > 0;

  return (
    <box id={id} flexDirection="column">
      {label && (
        <text>
          <b>{label}</b>
        </text>
      )}
      <box
        borderStyle={borderStyle}
        borderColor={borderColor}
        paddingLeft={paddingX}
        paddingRight={paddingX}
      >
        <text fg={theme.colors.mutedForeground}>{searchIcon}</text>
        <text
          fg={query ? theme.colors.foreground : theme.colors.mutedForeground}
        >
          {query || placeholder}
        </text>
        {isFocused && <text fg={theme.colors.focusRing}>{cursor}</text>}
      </box>
      {hasResults && (
        <box flexDirection="column" paddingLeft={2}>
          {filteredResults.map((item, idx) => {
            const isSelected = idx === selectedIndex;
            return (
              <box key={idx} flexDirection="row">
                <text
                  fg={
                    isSelected
                      ? theme.colors.focusRing
                      : theme.colors.mutedForeground
                  }
                >
                  {isSelected ? resultCursor : " ".repeat(resultCursor.length)}
                </text>
                <text
                  fg={
                    isSelected
                      ? theme.colors.foreground
                      : theme.colors.mutedForeground
                  }
                >
                  {getItemValue(item)}
                </text>
              </box>
            );
          })}
        </box>
      )}
    </box>
  );
};
